if ('IntersectionObserver' in window) {
  document.body.classList.add('js-ready');
  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target); }
    });
  }, { threshold: .08, rootMargin: '0px 0px -25px 0px' });
  document.querySelectorAll('.reveal').forEach((element) => observer.observe(element));
}

// A small magnetic offset stays confined to the call-to-action, never the cursor.
document.querySelectorAll('.magnetic').forEach((button) => {
  button.addEventListener('pointermove', (event) => {
    if (event.pointerType !== 'mouse' || motionQuery.matches) return;
    const rect = button.getBoundingClientRect();
    button.style.transform = `translate(${(event.clientX - rect.left - rect.width / 2) * .06}px, ${(event.clientY - rect.top - rect.height / 2) * .08}px)`;
  });
  button.addEventListener('pointerleave', () => { button.style.transform = ''; });
});
